from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")

# Access the Data and Lookup sheets
data_sheet = wb["Data"]
lookup_sheet = wb["Lookup"]

# Extract the years from the Lookup sheet
years = [lookup_sheet.cell(row=i, column=1).value for i in range(2, 13)]

# Identify the columns in the Data sheet that correspond to each year
year_columns = {}
for col in data_sheet.iter_cols(min_row=4, max_row=4, min_col=5, max_col=19):
    for cell in col:
        if cell.value in years:
            year_columns[cell.value] = cell.column

# Find the row in the Data sheet that contains "Total Expenses"
total_expenses_row = None
for row in data_sheet.iter_rows(min_row=1, max_row=26, min_col=1, max_col=16):
    for cell in row:
        if cell.value == "Total Expenses":
            total_expenses_row = cell.row
            break
    if total_expenses_row:
        break

# Extract the "Total Expenses" values for each year
total_expenses_values = {}
for year in years:
    if year in year_columns:
        col = year_columns[year]
        cell = data_sheet.cell(row=total_expenses_row, column=col)
        total_expenses_values[year] = cell.value

# Write the values to the Lookup sheet
for i in range(2, 13):
    year = lookup_sheet.cell(row=i, column=1).value
    value = total_expenses_values.get(year, "")
    lookup_sheet.cell(row=i, column=2, value=value)

# Save the workbook
wb.save("output.xlsx")
