from openpyxl import load_workbook
from openpyxl.styles import PatternFill, Font
from datetime import datetime, timedelta

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Define the fill color for colored cells
yellow_fill = PatternFill(start_color="FFFF00", end_color="FFFF00", fill_type="solid")

# Define the font
calibri_font = Font(name="Calibri")

# Get the list of holidays from column J
holidays = []
for row in ws.iter_rows(min_col=10, max_col=10, min_row=5, max_row=38):
    for cell in row:
        if cell.value:
            holidays.append(cell.value.date())

# Define the start and end dates
start_date = ws["B3"].value.date()
end_date = ws["F3"].value.date()

# Calculate workdays between start_date and end_date, excluding weekends and holidays
def is_workday(date):
    return date.weekday() < 5 and date not in holidays

workdays = []
current_date = start_date
while current_date <= end_date:
    if is_workday(current_date):
        workdays.append(current_date)
    current_date += timedelta(days=1)

# Fill in the values for columns B, D, F, and H
for i in range(7, 39):
    # Column B
    if i <= 32:
        ws[f"B{i}"].value = datetime(2021, 9, i - 6)
    elif i == 33:
        ws[f"B{i}"].value = ""

    # Column D
    if i <= 32:
        ws[f"D{i}"].value = datetime(2021, 10, i - 6)
    elif i == 33:
        ws[f"D{i}"].value = datetime(2021, 11, 1)
    elif i == 34:
        ws[f"D{i}"].value = datetime(2021, 11, 2)

    # Column F
    if i <= 32:
        ws[f"F{i}"].value = datetime(2021, 10, i - 6)
    elif i == 33:
        ws[f"F{i}"].value = datetime(2021, 11, 1)
    elif i == 34:
        ws[f"F{i}"].value = datetime(2021, 11, 2)

    # Column H
    if i <= len(workdays):
        ws[f"H{i}"].value = workdays[i - 7]
        ws[f"H{i}"].fill = yellow_fill
    else:
        ws[f"H{i}"].value = ""

# Apply formatting to the entire sheet
for row in ws.iter_rows():
    for cell in row:
        cell.font = calibri_font

# Save the workbook
wb.save("output.xlsx")
